insert into badminton_match.sessions (
  id,
  title,
  session_date,
  player_count,
  total_games,
  published_at,
  updated_at,
  snapshot
)
select
  session_id,
  coalesce(snapshot->'session'->>'title', ''),
  coalesce((snapshot->'session'->>'date')::date, created_at::date),
  coalesce(jsonb_array_length(coalesce(snapshot->'players', '[]'::jsonb)), 0),
  coalesce(jsonb_array_length(coalesce(snapshot->'schedule', '[]'::jsonb)), 0),
  created_at,
  updated_at,
  snapshot
from legacy_sessions
on conflict (id) do update
  set title = excluded.title,
      session_date = excluded.session_date,
      player_count = excluded.player_count,
      total_games = excluded.total_games,
      published_at = excluded.published_at,
      updated_at = excluded.updated_at,
      snapshot = excluded.snapshot;

