insert into badminton_match.tournaments (
  id,
  name,
  event_date,
  updated_at,
  snapshot
)
select
  tournament_id,
  coalesce(snapshot->>'name', tournament_id),
  coalesce((snapshot->>'date')::date, created_at::date),
  updated_at,
  snapshot
from legacy_tournaments
on conflict (id) do update
  set name = excluded.name,
      event_date = excluded.event_date,
      updated_at = excluded.updated_at,
      snapshot = excluded.snapshot;

